#!/usr/bin/env python3
"""Одноразовое преобразование контента (решение владельца, сентябрь 2026): ссылки на стихи остаются
только в книгах без чёткой структуры (Псалтирь, Притчи, Екклесиаст); в остальных вопросах ссылок нет —
команда читает весь район. Скобочные ссылки убираются автоматически, ссылки внутри фразы — по словарю замен."""
import json, re, sys
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
KEEP = {"psa", "pro", "ecc"}
PAREN = re.compile(r"\s*\((?:[^()]*?\d+:\d+[^()]*)\)")
INLINE = re.compile(r"\d+:\d+")

