def clean(p: str) -> str:
    p = PAREN.sub("", p)
    p = re.sub(r"\s+([?!.,;:])", r"\1", p)
    p = re.sub(r"[ \t]{2,}", " ", p).strip()
    return p

changed = 0; left = []
for f in sorted((ROOT / "content/cities").glob("*.json")):
    d = json.loads(f.read_text()); code = d["book"]
    if code in KEEP: continue
    for i, t in enumerate(d["tasks"]):
        new = REWRITE.get((code, i), t["prompt"])
        new = clean(new)
        if INLINE.search(new): left.append((code, i, new[:100]))
        if new != t["prompt"]: t["prompt"] = new; changed += 1
    f.write_text(json.dumps(d, ensure_ascii=False, indent=2) + "\n")
print("changed", changed, "still with refs", left)
